 import { BookOpen, ArrowLeft, Network, Clapperboard, Film, Library } from '@lucide/svelte';
 let {projects,project,view,onselect,disabled=false,actions}:{projects:{id:string;name:string}[];project:string;view:'story'|'canvas'|'edit'|'resources';onselect:(id:string)=>void;disabled?:boolean;actions?:Snippet}=$props();
 const destinations=[{id:'story',label:'Story',path:'/studio?tab=storyboard',icon:Clapperboard},{id:'canvas',label:'Canvas',path:'/studio',icon:Network},{id:'edit',label:'Edit',path:'/studio/editor',icon:Film}];
 function href(path:string){return `${path}${path.includes('?')?'&':'?'}project=${encodeURIComponent(project)}`;}
</script>
<header class="project-navigation">
 <div class="project-identity"><a href="/projects" aria-label="All projects"><ArrowLeft size={17}/></a><label class="sr-only" for="active-project">Current project</label><select id="active-project" value={project} {disabled} onchange={event=>{const next=event.currentTarget.value;event.currentTarget.value=project;onselect(next);}}><option value="" disabled>Choose a project</option>{#each projects as item}<option value={item.id}>{item.name}</option>{/each}</select></div>
